async function answerListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  let listed: SessionSummary[] | undefined;
  try {
    // The user is the session's, read here and never from the frame the validator already stripped.
    listed = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listing sessions failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
    return;
  }
  sendSessionList(ws, listed ?? []);
}

